import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.find.js";
import { Terminal } from 'xterm';
import { FitAddon } from 'xterm-addon-fit';
import 'xterm/css/xterm.css';
import { serverApi, roomApi } from '@/api/index';
export default {
  name: 'WorldLog',
  props: {
    title: {
      type: String,
      default: '世界日志'
    },
    archiveName: {
      type: String,
      default: ''
    },
    worldName: {
      type: String,
      default: ''
    }
  },
  data() {
    return {
      terminal: null,
      fitAddon: null,
      selectedArchive: this.archiveName || '',
      selectedWorld: this.worldName || '',
      loading: false,
      autoRefresh: false,
      refreshInterval: null,
      refreshRate: 30000,
      // 30秒自动刷新一次
      archives: [],
      logContent: ''
    };
  },
  computed: {
    currentArchiveWorlds() {
      if (!this.selectedArchive) return [];
      const archive = this.archives.find(a => a.name === this.selectedArchive);
      return archive && archive.worlds ? archive.worlds : [];
    }
  },
  mounted() {
    this.initTerminal();
    this.loadArchives();

    // 如果设置了初始存档和世界，尝试加载日志
    if (this.selectedArchive && this.selectedWorld) {
      this.$nextTick(() => {
        this.loadLog();
      });
    }

    // 监听窗口大小变化，调整终端大小
    window.addEventListener('resize', this.onResize);
  },
  beforeDestroy() {
    // 清理事件监听
    window.removeEventListener('resize', this.onResize);

    // 清除自动刷新定时器
    this.clearRefreshInterval();

    // 销毁终端
    if (this.terminal) {
      this.terminal.dispose();
    }
  },
  methods: {
    initTerminal() {
      // 创建终端实例
      this.terminal = new Terminal({
        cursorBlink: false,
        disableStdin: true,
        // 禁用输入
        fontSize: 14,
        fontFamily: 'Menlo, Monaco, "Courier New", monospace',
        theme: {
          background: '#1e1e1e',
          foreground: '#f0f0f0',
          cursor: 'transparent'
        },
        rendererType: 'canvas',
        scrollback: 5000
      });

      // 创建自适应插件
      this.fitAddon = new FitAddon();
      this.terminal.loadAddon(this.fitAddon);

      // 挂载终端
      this.terminal.open(this.$refs.terminal);

      // 调整大小
      this.$nextTick(() => {
        this.fitAddon.fit();
      });

      // 写入欢迎信息
      this.terminal.writeln('\x1B[1;3;36m欢迎使用饥荒联机版服务器日志查看器\x1B[0m');
      this.terminal.writeln('\x1B[90m请选择一个存档和世界以查看其日志记录...\x1B[0m');
      this.terminal.writeln('');
    },
    loadArchives() {
      this.loading = true;
      roomApi.getRoomList().then(response => {
        // 检查是否是数组
        if (Array.isArray(response)) {
          this.archives = response;
        }
        // 如果设置了初始存档，但没有世界，尝试从加载的数据中找到对应的世界
        if (this.selectedArchive && !this.selectedWorld) {
          const archive = this.archives.find(a => a.name === this.selectedArchive);
          if (archive && archive.worlds && archive.worlds.length > 0) {
            this.selectedWorld = archive.worlds[0].name;
          }
        }
      }).catch(error => {
        console.error('获取存档列表失败:', error);
        this.terminal.writeln('\x1B[31m获取存档列表失败，请稍后重试。\x1B[0m');
      }).finally(() => {
        this.loading = false;
      });
    },
    handleArchiveChange() {
      // 当切换存档时，重置所选世界
      this.selectedWorld = '';

      // 如果当前存档有世界，自动选择第一个
      if (this.currentArchiveWorlds.length > 0) {
        this.selectedWorld = this.currentArchiveWorlds[0].name;
        this.loadLog();
      }
    },
    handleWorldChange() {
      this.loadLog();
    },
    onResize() {
      if (this.fitAddon) {
        this.fitAddon.fit();
      }
    },
    refreshLog() {
      if (this.selectedArchive && this.selectedWorld) {
        this.loadLog();
      } else {
        this.$message.warning('请先选择存档和世界');
      }
    },
    formatWorldType(type) {
      const typeMap = {
        'forest': '主世界',
        'cave': '洞穴',
        'unknown': '未知'
      };
      return typeMap[type] || type;
    },
    loadLog() {
      if (!this.selectedArchive || !this.selectedWorld) return;
      this.loading = true;

      // 清空终端内容
      this.terminal.clear();
      const archive = this.selectedArchive;
      const world = this.selectedWorld;

      // 使用真实API调用获取日志
      serverApi.getServerLogStream(archive, world).then(response => {
        // 写入日志标题
        this.terminal.writeln(`\x1B[1;32m=== ${archive}/${world} 日志记录 ===\x1B[0m`);
        this.terminal.writeln('');

        // 处理返回的日志数据
        let logs = [];
        if (response.data) {
          if (typeof response.data === 'string') {
            logs = response.data.split('\n');
          } else if (Array.isArray(response.data)) {
            logs = response.data;
          }
        }
        if (logs.length === 0) {
          this.terminal.writeln('\x1B[33m没有找到日志记录\x1B[0m');
        } else {
          // 逐行写入日志
          this.writeLogsWithDelay(logs, 10);
        }
      }).catch(error => {
        console.error('获取日志失败:', error);
        this.terminal.writeln('\x1B[31m获取日志失败，请稍后重试。\x1B[0m');
        this.terminal.writeln(`\x1B[31m错误信息: ${error.message || '未知错误'}\x1B[0m`);
      }).finally(() => {
        this.loading = false;
      });
    },
    // 使用延迟逐行写入日志
    writeLogsWithDelay(logs, delay) {
      if (logs.length === 0) {
        this.loading = false;
        return;
      }
      const logBatch = logs.slice(0, 50); // 一次处理50行
      const remaining = logs.slice(50);

      // 批量写入
      for (const log of logBatch) {
        // 根据日志类型添加颜色
        let coloredLog = log;
        if (log.includes('[INFO]')) {
          coloredLog = log.replace('[INFO]', '\x1B[32m[INFO]\x1B[0m');
        } else if (log.includes('[WARN]') || log.includes('[WARNING]')) {
          coloredLog = log.replace(/\[(WARN|WARNING)\]/, '\x1B[33m[$1]\x1B[0m');
        } else if (log.includes('[ERROR]') || log.includes('[FATAL]')) {
          coloredLog = log.replace(/\[(ERROR|FATAL)\]/, '\x1B[31m[$1]\x1B[0m');
        } else if (log.includes('[DEBUG]')) {
          coloredLog = log.replace('[DEBUG]', '\x1B[36m[DEBUG]\x1B[0m');
        } else if (log.includes('[SYSTEM]')) {
          coloredLog = log.replace('[SYSTEM]', '\x1B[35m[SYSTEM]\x1B[0m');
        }
        this.terminal.writeln(coloredLog);
      }

      // 滚动到底部
      this.scrollToBottom();

      // 如果还有剩余日志，继续处理
      if (remaining.length > 0) {
        setTimeout(() => {
          this.writeLogsWithDelay(remaining, delay);
        }, delay);
      }
    },
    // 滚动到终端底部
    scrollToBottom() {
      if (this.terminal) {
        this.terminal.scrollToBottom();
      }
    },
    // 处理自动刷新开关变化
    handleAutoRefreshChange(value) {
      if (value) {
        this.startAutoRefresh();
      } else {
        this.clearRefreshInterval();
      }
    },
    // 启动自动刷新
    startAutoRefresh() {
      // 先清除可能存在的旧定时器
      this.clearRefreshInterval();

      // 如果没有选择存档或世界，不启动自动刷新
      if (!this.selectedArchive || !this.selectedWorld) {
        this.$message.warning('请先选择存档和世界');
        this.autoRefresh = false;
        return;
      }

      // 创建新的定时器
      this.refreshInterval = setInterval(() => {
        if (!this.loading) {
          this.appendNewLogs();
        }
      }, this.refreshRate);
      this.$message.success(`已开启自动刷新，间隔${this.refreshRate / 1000}秒`);
    },
    // 清除自动刷新定时器
    clearRefreshInterval() {
      if (this.refreshInterval) {
        clearInterval(this.refreshInterval);
        this.refreshInterval = null;
      }
    },
    // 仅追加新日志，不清空现有日志
    appendNewLogs() {
      if (!this.selectedArchive || !this.selectedWorld) return;
      serverApi.getServerLogStream(this.selectedArchive, this.selectedWorld).then(response => {
        // 处理返回的日志数据
        let logs = [];
        if (response.data) {
          if (typeof response.data === 'string') {
            logs = response.data.split('\n');
          } else if (Array.isArray(response.data)) {
            logs = response.data;
          }
        }

        // 只显示最新的10行日志
        const newLogs = logs.slice(-10);
        if (newLogs.length > 0) {
          this.writeLogsWithDelay(newLogs, 50);
        }
      }).catch(error => {
        console.error('自动刷新日志失败:', error);
        // 出错时停止自动刷新
        this.autoRefresh = false;
        this.clearRefreshInterval();
        this.terminal.writeln('\x1B[31m自动刷新失败，已停止。\x1B[0m');
      });
    }
  },
  watch: {
    archiveName(newValue) {
      this.selectedArchive = newValue;
      if (newValue && this.archives.length > 0) {
        const archive = this.archives.find(a => a.name === newValue);
        if (archive && archive.worlds && archive.worlds.length > 0 && !this.selectedWorld) {
          this.selectedWorld = archive.worlds[0].name;
        }
        if (this.selectedWorld) {
          this.loadLog();
        }
      }
    },
    worldName(newValue) {
      this.selectedWorld = newValue;
      if (this.selectedArchive && newValue) {
        this.loadLog();
      }
    }
  }
};
